/**
 * issue #58 M2/M3: a small, explicit HTTP ingress/egress transport around
 * `executeFlow`. This module is intentionally NOT wired into `worker.js`
 * yet (that is M5's job) - it is a standalone, dependency-injected factory
 * so it can be started/stopped cleanly by the Activity/combined runner
 * process once that wiring happens.
 *
 * Architecture reminder (see issue #58): HTTP is an ingress/egress
 * transport around `executeFlow`; it is not a second Node-RED routing
 * engine, and the HTTP socket itself is never durable. Only two fixed
 * routes exist:
 *
 *   POST /_node-red-temporal/http/async/:startNodeId
 *   POST /_node-red-temporal/http/sync/:startNodeId/:resultNodeId
 *
 * No arbitrary URL templates, no Express dependency - just Node's built-in
 * `http` module plus injected dependencies.
 */

"use strict";

const http = require("http");
const crypto = require("crypto");

// issue #58: cap raw request body at 256 KiB, checked WHILE streaming (not
// after buffering unbounded), so an oversized body is aborted as soon as
// the cap is exceeded.
const MAX_BODY_BYTES = 256 * 1024;

// issue #58: an `Idempotency-Key` header larger than this is rejected
// outright (400) before it is ever hashed/used.
const MAX_IDEMPOTENCY_KEY_BYTES = 256;

// issue #58 M4: default bound (ms) for the sync route's wait on
// `handle.result()` when `deps.syncTimeoutMs` is not supplied. M5 is
// expected to wire a `--http-sync-timeout-ms` CLI flag through to this
// same `deps.syncTimeoutMs`.
const DEFAULT_SYNC_TIMEOUT_MS = 60000;

// issue #58: headers that must never be forwarded into the constructed
// message envelope or Workflow input, checked case-insensitively (Node's
// http module already lower-cases incoming header names).
const STRIPPED_HEADERS = [
    "authorization",
    "proxy-authorization",
    "cookie",
    "set-cookie",
    "idempotency-key"
];

const ASYNC_ROUTE_PREFIX = "/_node-red-temporal/http/async/";
const SYNC_ROUTE_PREFIX = "/_node-red-temporal/http/sync/";

/**
 * Matches `POST /_node-red-temporal/http/async/:startNodeId`.
 *
 * @param {string} method
 * @param {string} pathname
 * @returns {{startNodeId:string}|null}
 */
function matchAsyncRoute(method, pathname) {
    if (method !== "POST") {
        return null;
    }
    if (!pathname.startsWith(ASYNC_ROUTE_PREFIX)) {
        return null;
    }
    const rest = pathname.slice(ASYNC_ROUTE_PREFIX.length);
    if (!rest || rest.indexOf("/") !== -1) {
        return null;
    }
    return { startNodeId: decodeURIComponent(rest) };
}

/**
 * Matches `POST /_node-red-temporal/http/sync/:startNodeId/:resultNodeId`.
 *
 * @param {string} method
 * @param {string} pathname
 * @returns {{startNodeId:string, resultNodeId:string}|null}
 */
function matchSyncRoute(method, pathname) {
    if (method !== "POST") {
        return null;
    }
    if (!pathname.startsWith(SYNC_ROUTE_PREFIX)) {
        return null;
    }
    const rest = pathname.slice(SYNC_ROUTE_PREFIX.length);
    const parts = rest.split("/");
    if (parts.length !== 2 || !parts[0] || !parts[1]) {
        return null;
    }
    return { startNodeId: decodeURIComponent(parts[0]), resultNodeId: decodeURIComponent(parts[1]) };
}

/**
 * Strips sensitive headers (case-insensitively - Node already lower-cases
 * incoming header names) and drops any header whose value is not a plain
 * string/string[] (defensive; Node's `http` module only ever hands us
 * those two shapes for request headers).
 *
 * @param {object} headers - `req.headers` as provided by Node's http module
 * @returns {object} sanitized shallow copy
 */
function sanitizeHeaders(headers) {
    const out = {};
    Object.keys(headers || {}).forEach(function(name) {
        if (STRIPPED_HEADERS.indexOf(name.toLowerCase()) !== -1) {
            return;
        }
        out[name] = headers[name];
    });
    return out;
}

/**
 * Reads the request body while streaming, aborting as soon as
 * `MAX_BODY_BYTES` is exceeded (never buffers unbounded first).
 *
 * @param {import("http").IncomingMessage} req
 * @returns {Promise<Buffer>}
 */
function readBodyCapped(req) {
    return new Promise(function(resolve, reject) {
        let total = 0;
        const chunks = [];
        let rejected = false;

        function onData(chunk) {
            if (rejected) {
                return;
            }
            total += chunk.length;
            if (total > MAX_BODY_BYTES) {
                rejected = true;
                req.removeListener("data", onData);
                req.removeListener("end", onEnd);
                const err = new Error("request body exceeds maximum size");
                err.code = "BODY_TOO_LARGE";
                reject(err);
                return;
            }
            chunks.push(chunk);
        }

        function onEnd() {
            if (rejected) {
                return;
            }
            resolve(Buffer.concat(chunks));
        }

        req.on("data", onData);
        req.on("end", onEnd);
        req.on("error", function(err) {
            if (rejected) {
                return;
            }
            rejected = true;
            reject(err);
        });
    });
}

/**
 * Parses a capped body Buffer into `msg.payload` per the issue #58 body
 * contract: JSON when Content-Type is JSON, otherwise UTF-8 text, empty
 * body => `undefined`.
 *
 * @param {Buffer} bodyBuffer
 * @param {string} [contentType]
 * @returns {*} the parsed payload
 * @throws {Error} with `.code === "INVALID_JSON"` on malformed JSON
 */
function parseBody(bodyBuffer, contentType) {
    if (!bodyBuffer || bodyBuffer.length === 0) {
        return undefined;
    }
    const isJson = typeof contentType === "string" && contentType.toLowerCase().indexOf("application/json") !== -1;
    const text = bodyBuffer.toString("utf8");
    if (!isJson) {
        return text;
    }
    try {
        return JSON.parse(text);
    } catch (err) {
        const parseErr = new Error("malformed JSON request body");
        parseErr.code = "INVALID_JSON";
        throw parseErr;
    }
}

/**
 * Builds the one ordinary serializable Node-RED message this whole module
 * exists to construct - no `msg.req`/`msg.res`/socket/stream/functions ever
 * placed on the envelope.
 *
 * @param {import("http").IncomingMessage} req
 * @param {string} pathname
 * @param {URLSearchParams} searchParams
 * @param {*} payload
 * @returns {{payload:*, http:{method:string, path:string, query:object, headers:object}}}
 */
function buildEnvelope(req, pathname, searchParams, payload) {
    const query = {};
    searchParams.forEach(function(value, key) {
        query[key] = value;
    });
    return {
        payload: payload,
        http: {
            method: req.method,
            path: pathname,
            query: query,
            headers: sanitizeHeaders(req.headers)
        }
    };
}

/**
 * Derives a bounded, non-reversible Workflow ID. Without an
 * `Idempotency-Key`, a fresh random UUID is used (never reused/derivable).
 * With one, the raw key is SHA-256 hashed and never placed in the Workflow
 * ID/history itself.
 *
 * @param {"async"|"sync"} mode
 * @param {string} startNodeId
 * @param {string} [resultNodeId]
 * @param {string} [idempotencyKey] - raw header value, already validated <= MAX_IDEMPOTENCY_KEY_BYTES
 * @returns {string}
 */
function deriveWorkflowId(mode, startNodeId, resultNodeId, idempotencyKey) {
    const identity = resultNodeId ? `${startNodeId}:${resultNodeId}` : startNodeId;
    if (!idempotencyKey) {
        return `http:${mode}:${identity}:${crypto.randomUUID()}`;
    }
    const hash = crypto.createHash("sha256").update(idempotencyKey, "utf8").digest("hex");
    return `http:${mode}:${identity}:${hash}`;
}

/**
 * Small JSON error response helper - never includes stack traces, only the
 * fixed `{error:string}` (plus optional extra fields like `workflowId`).
 *
 * @param {import("http").ServerResponse} res
 * @param {number} statusCode
 * @param {string} message
 * @param {object} [extra]
 */
function sendJsonError(res, statusCode, message, extra) {
    sendJson(res, statusCode, Object.assign({ error: message }, extra || {}));
}

/**
 * @param {import("http").ServerResponse} res
 * @param {number} statusCode
 * @param {object} body
 */
function sendJson(res, statusCode, body) {
    const text = JSON.stringify(body);
    res.writeHead(statusCode, { "Content-Type": "application/json; charset=utf-8" });
    res.end(text);
}

/**
 * Starts (or dedups, per Idempotency-Key) an `executeFlow` Workflow for one
 * HTTP-triggered request. Shared by both the async route (this step) and
 * the sync route's Workflow-start half (full sync response mapping is
 * M4's job - see the TODO in `handleSyncRoute` below).
 *
 * @param {object} deps
 * @param {function(): Promise<object>} deps.getClient
 * @param {{workflowTaskQueue:string, activityTaskQueue:string}} deps.temporalConfig
 * @param {number} [deps.nodeExecutionTimeoutMs]
 * @param {"async"|"sync"} mode
 * @param {string} startNodeId
 * @param {string|undefined} resultNodeId
 * @param {object} flowInfo - `{graph, nodeMeta, flowVersion}`
 * @param {object} envelope - the constructed message envelope (becomes `startMsg`)
 * @param {string|undefined} idempotencyKey - raw header value
 * @returns {Promise<{workflowId:string, reused:boolean, client:object}>}
 * @throws on any Temporal failure other than duplicate-start
 */
async function startFlowWorkflow(deps, mode, startNodeId, resultNodeId, flowInfo, envelope, idempotencyKey) {
    const { WorkflowIdReusePolicy, WorkflowExecutionAlreadyStartedError } = require("@temporalio/client");
    const workflowId = deriveWorkflowId(mode, startNodeId, resultNodeId, idempotencyKey);
    const client = await deps.getClient();

    const args = [{
        graph: flowInfo.graph,
        nodeMeta: flowInfo.nodeMeta,
        flowVersion: flowInfo.flowVersion,
        startNode: startNodeId,
        startMsg: envelope,
        activityTaskQueue: deps.temporalConfig.activityTaskQueue,
        nodeExecutionTimeoutMs: deps.nodeExecutionTimeoutMs
    }];
    if (resultNodeId) {
        args[0].resultNodeId = resultNodeId;
    }

    try {
        await client.workflow.start("executeFlow", {
            taskQueue: deps.temporalConfig.workflowTaskQueue,
            workflowId: workflowId,
            workflowIdReusePolicy: WorkflowIdReusePolicy.REJECT_DUPLICATE,
            args: args
        });
        return { workflowId: workflowId, reused: false, client: client };
    } catch (err) {
        if (err instanceof WorkflowExecutionAlreadyStartedError) {
            // issue #58: the Workflow was already accepted by an earlier
            // (deduped) request - obtain its handle so callers CAN act on
            // it, but do not start a duplicate. The sync route (M4) uses
            // this same `client` to call `getHandle(workflowId)` again and
            // await its result.
            client.workflow.getHandle(workflowId);
            return { workflowId: workflowId, reused: true, client: client };
        }
        throw err;
    }
}

/**
 * Handles `POST /_node-red-temporal/http/async/:startNodeId` end to end:
 * validate -> parse body -> build envelope -> start Workflow -> 202.
 *
 * @param {object} deps - see `createHttpIngressServer`
 * @param {{startNodeId:string}} params
 * @param {import("http").IncomingMessage} req
 * @param {import("http").ServerResponse} res
 * @param {string} pathname
 * @param {URLSearchParams} searchParams
 */
async function handleAsyncRoute(deps, params, req, res, pathname, searchParams) {
    await handleStartRoute(deps, "async", params.startNodeId, undefined, req, res, pathname, searchParams, respondAsync);
}

/**
 * Async route's response callback: always 202 + `{workflowId, reused}`,
 * regardless of whether the Workflow was freshly started or deduped.
 *
 * @param {object} deps
 * @param {import("http").ServerResponse} res
 * @param {{workflowId:string, reused:boolean, client:object}} started
 */
async function respondAsync(deps, res, started) {
    sendJson(res, 202, { workflowId: started.workflowId, reused: started.reused });
}

/**
 * Handles `POST /_node-red-temporal/http/sync/:startNodeId/:resultNodeId`
 * end to end (issue #58 M4): after the Workflow starts (or is deduped),
 * await its `handle.result()` bounded by `deps.syncTimeoutMs`, then map the
 * resolved `{resultMsg}` (or thrown `ApplicationFailure`) into the real
 * HTTP response - see `respondSync` for the full mapping.
 *
 * @param {object} deps
 * @param {{startNodeId:string, resultNodeId:string}} params
 * @param {import("http").IncomingMessage} req
 * @param {import("http").ServerResponse} res
 * @param {string} pathname
 * @param {URLSearchParams} searchParams
 */
async function handleSyncRoute(deps, params, req, res, pathname, searchParams) {
    await handleStartRoute(deps, "sync", params.startNodeId, params.resultNodeId, req, res, pathname, searchParams, respondSync);
}

/**
 * Sync route's response callback (issue #58 M4): waits on the started (or
 * reused) Workflow's `handle.result()`, bounded by `deps.syncTimeoutMs`
 * (default 60000ms), and maps the outcome to an HTTP response.
 *
 * Bounding strategy: a plain `Promise.race` between `handle.result()` and a
 * timer - deliberately not a gRPC-level deadline, since that would require
 * a separate `Connection`/`Client` scoped to this one call and issue #58
 * only requires "the HTTP connection must not wait forever", not that the
 * Workflow itself be aborted. On timeout the Workflow is NEVER cancelled or
 * terminated - it keeps running; only the HTTP wait ends. The loser
 * promise (`handle.result()` after a timeout, or the timer after a result)
 * is given a no-op `.catch()`/is cleared so neither leaks an unhandled
 * rejection or a dangling timer.
 *
 * If the client already disconnected (`req` 'aborted'/'close') before the
 * Workflow settles, no response is written at all - the Workflow is still
 * left running untouched.
 *
 * @param {object} deps
 * @param {number} [deps.syncTimeoutMs]
 * @param {import("http").ServerResponse} res
 * @param {{workflowId:string, reused:boolean, client:object}} started
 * @param {import("http").IncomingMessage} req
 */
async function respondSync(deps, res, started, req) {
    let clientDisconnected = false;
    function onDisconnect() {
        clientDisconnected = true;
    }
    req.on("aborted", onDisconnect);
    req.on("close", onDisconnect);

    const timeoutMs = typeof deps.syncTimeoutMs === "number" ? deps.syncTimeoutMs : DEFAULT_SYNC_TIMEOUT_MS;
    const handle = started.client.workflow.getHandle(started.workflowId);

    let timer;
    const timeoutPromise = new Promise(function(resolve) {
        timer = setTimeout(function() {
            resolve({ timedOut: true });
        }, timeoutMs);
    });

    let outcome;
    try {
        outcome = await Promise.race([
            handle.result().then(function(result) { return { timedOut: false, result: result }; }),
            timeoutPromise
        ]);
    } catch (err) {
        clearTimeout(timer);
        // issue #58 M4: the Workflow itself failed (FLOW_RESULT_MISSING,
        // FLOW_RESULT_AMBIGUOUS, or any other Workflow failure) - map to
        // 500, never crash the process, never cancel/terminate the
        // Workflow (it already finished by the time this rejects).
        writeSyncErrorResponse(res, req, clientDisconnected, err, started.workflowId);
        return;
    }
    clearTimeout(timer);

    if (outcome.timedOut) {
        // issue #58 M4: bounded-wait elapsed while the Workflow is still
        // running. Stop waiting on this HTTP connection but let the
        // Workflow continue; attach a no-op catch to `handle.result()` so
        // its eventual settlement (success or failure) never surfaces as
        // an unhandled rejection.
        handle.result().catch(function() {});
        if (!clientDisconnected && !res.writableEnded && !res.headersSent) {
            sendJson(res, 504, { error: "workflow result timed out", workflowId: started.workflowId });
        }
        return;
    }

    if (clientDisconnected || res.writableEnded || res.headersSent) {
        return;
    }
    writeSyncSuccessResponse(res, outcome.result);
}

/**
 * Headers that must never be forwarded from `resultMsg.headers` into the
 * HTTP response - Node computes framing/content-length itself.
 */
const STRIPPED_RESPONSE_HEADERS = [
    "connection",
    "keep-alive",
    "transfer-encoding",
    "content-length",
    "upgrade",
    "proxy-connection"
];

/**
 * Maps a resolved `runFlow`/`executeFlow` result (`{flowVersion, lastNode,
 * resultMsg}`) to the actual HTTP response - see the module docblock's
 * "Response mapping" contract (issue #58 M4).
 *
 * Design choice (documented per the task's explicit ask): an
 * out-of-range/non-integer `resultMsg.statusCode` is treated as a
 * fallback-to-200 case, not a 500 - the rest of the response (headers,
 * body) is still constructed normally. Only a `resultMsg` that is not a
 * plain object at all makes response construction impossible, so that
 * case alone maps to 500.
 *
 * @param {import("http").ServerResponse} res
 * @param {{flowVersion:string, lastNode:(string|undefined), resultMsg:*}} result
 */
function writeSyncSuccessResponse(res, result) {
    const resultMsg = result && result.resultMsg;
    if (resultMsg === null || typeof resultMsg !== "object" || Array.isArray(resultMsg)) {
        sendJsonError(res, 500, "flow result message is missing or invalid");
        return;
    }

    const statusCode = isValidHttpStatus(resultMsg.statusCode) ? resultMsg.statusCode : 200;

    const headers = {};
    if (resultMsg.headers && typeof resultMsg.headers === "object" && !Array.isArray(resultMsg.headers)) {
        Object.keys(resultMsg.headers).forEach(function(name) {
            if (STRIPPED_RESPONSE_HEADERS.indexOf(name.toLowerCase()) !== -1) {
                return;
            }
            const value = resultMsg.headers[name];
            if (value === null || value === undefined) {
                return;
            }
            headers[name] = String(value);
        });
    }

    const hasContentType = Object.keys(headers).some(function(name) { return name.toLowerCase() === "content-type"; });
    const payload = resultMsg.payload;

    let body;
    if (payload === undefined) {
        body = Buffer.alloc(0);
    } else if (Buffer.isBuffer(payload) || payload instanceof Uint8Array) {
        body = Buffer.from(payload);
    } else if (typeof payload === "string") {
        body = Buffer.from(payload, "utf8");
        if (!hasContentType) {
            headers["Content-Type"] = "text/plain; charset=utf-8";
        }
    } else {
        body = Buffer.from(JSON.stringify(payload), "utf8");
        if (!hasContentType) {
            headers["Content-Type"] = "application/json; charset=utf-8";
        }
    }

    res.writeHead(statusCode, headers);
    res.end(body);
}

/**
 * @param {*} value
 * @returns {boolean} true iff `value` is an integer in `[100, 599]`
 */
function isValidHttpStatus(value) {
    return typeof value === "number" && Number.isInteger(value) && value >= 100 && value <= 599;
}

/**
 * Maps a rejected `handle.result()` to a 500 JSON error response,
 * surfacing the underlying `ApplicationFailure`'s `.type`
 * (`FLOW_RESULT_MISSING`/`FLOW_RESULT_AMBIGUOUS`/etc) when present.
 * `WorkflowFailedError` (thrown by `@temporalio/client`) wraps the actual
 * Workflow failure in `.cause`; plain `ApplicationFailure`-shaped errors
 * (as used by this module's own test stubs) are also accepted directly.
 *
 * @param {import("http").ServerResponse} res
 * @param {import("http").IncomingMessage} req
 * @param {boolean} clientDisconnected
 * @param {Error} err
 * @param {string} workflowId
 */
function writeSyncErrorResponse(res, req, clientDisconnected, err, workflowId) {
    if (clientDisconnected || res.writableEnded || res.headersSent) {
        return;
    }
    const cause = (err && err.cause) || err;
    const type = cause && cause.type;
    console.error(`[node-red-temporal] http ingress: sync workflow failed workflowId=${workflowId}: ${err && err.message}`);
    sendJson(res, 500, Object.assign({ error: "workflow failed", workflowId: workflowId }, type ? { type: type } : {}));
}

/**
 * Shared start-route implementation for both async and sync: validate
 * startNodeId -> read/parse capped body -> build envelope -> start (or
 * dedup) the Workflow -> hand off to `mode`-specific `respond` callback for
 * the actual HTTP response (202 for async, bounded-wait+mapping for sync -
 * issue #58 M4).
 *
 * @param {object} deps
 * @param {"async"|"sync"} mode
 * @param {string} startNodeId
 * @param {string|undefined} resultNodeId
 * @param {import("http").IncomingMessage} req
 * @param {import("http").ServerResponse} res
 * @param {string} pathname
 * @param {URLSearchParams} searchParams
 * @param {function(object, import("http").ServerResponse, {workflowId:string, reused:boolean, client:object}, import("http").IncomingMessage): Promise<void>} respond
 */
async function handleStartRoute(deps, mode, startNodeId, resultNodeId, req, res, pathname, searchParams, respond) {
    const node = deps.getNode(startNodeId);
    if (!node) {
        console.error(`[node-red-temporal] http ingress: unknown startNodeId "${startNodeId}" (${mode})`);
        sendJsonError(res, 400, "unknown startNodeId");
        return;
    }

    const idempotencyKeyRaw = req.headers["idempotency-key"];
    if (typeof idempotencyKeyRaw === "string" && Buffer.byteLength(idempotencyKeyRaw, "utf8") > MAX_IDEMPOTENCY_KEY_BYTES) {
        sendJsonError(res, 400, "Idempotency-Key header too large");
        return;
    }

    let bodyBuffer;
    try {
        bodyBuffer = await readBodyCapped(req);
    } catch (err) {
        if (err.code === "BODY_TOO_LARGE") {
            sendJsonError(res, 413, "request body too large");
            return;
        }
        console.error(`[node-red-temporal] http ingress: body read error for "${startNodeId}" (${mode}): ${err.message}`);
        sendJsonError(res, 400, "request read error");
        return;
    }

    let payload;
    try {
        payload = parseBody(bodyBuffer, req.headers["content-type"]);
    } catch (err) {
        sendJsonError(res, 400, "malformed JSON request body");
        return;
    }

    const envelope = buildEnvelope(req, pathname, searchParams, payload);

    let flowInfo;
    try {
        flowInfo = typeof deps.currentFlowInfo === "function" ? await deps.currentFlowInfo() : deps.currentFlowInfo;
    } catch (err) {
        console.error(`[node-red-temporal] http ingress: failed to read current flow info (${mode}): ${err.message}`);
        sendJsonError(res, 503, "runner unavailable");
        return;
    }

    let started;
    try {
        started = await startFlowWorkflow(deps, mode, startNodeId, resultNodeId, flowInfo, envelope, idempotencyKeyRaw);
    } catch (err) {
        console.error(`[node-red-temporal] http ingress: workflow start failed for "${startNodeId}" (${mode}): ${err.message}`);
        sendJsonError(res, 503, "workflow start failed");
        return;
    }

    console.log(`[node-red-temporal] http ingress: ${mode} start node="${startNodeId}" outcome=${started.reused ? "reused" : "started"}`);
    await respond(deps, res, started, req);
}

/**
 * Top-level request handler: matches one of the two fixed routes and
 * dispatches, or responds `404` for anything else.
 *
 * @param {object} deps
 * @returns {function(import("http").IncomingMessage, import("http").ServerResponse): void}
 */
function createRequestListener(deps) {
    return function requestListener(req, res) {
        const parsedUrl = new URL(req.url, "http://localhost");
        const pathname = parsedUrl.pathname;

        const asyncParams = matchAsyncRoute(req.method, pathname);
        if (asyncParams) {
            handleAsyncRoute(deps, asyncParams, req, res, pathname, parsedUrl.searchParams).catch(function(err) {
                console.error(`[node-red-temporal] http ingress: unhandled error: ${err.message}`);
                if (!res.headersSent) {
                    sendJsonError(res, 503, "internal error");
                }
            });
            return;
        }

        const syncParams = matchSyncRoute(req.method, pathname);
        if (syncParams) {
            handleSyncRoute(deps, syncParams, req, res, pathname, parsedUrl.searchParams).catch(function(err) {
                console.error(`[node-red-temporal] http ingress: unhandled error: ${err.message}`);
                if (!res.headersSent) {
                    sendJsonError(res, 503, "internal error");
                }
            });
            return;
        }

        sendJsonError(res, 404, "not found");
    };
}

/**
 * Creates (but does not start) an HTTP ingress server. `worker.js` (M5) is
 * expected to call `listen()`/`close()` around the Activity/combined
 * runner's own lifecycle; this module never reads real Node-RED state
 * itself, matching the rest of this codebase's DI style.
 *
 * @param {object} deps
 * @param {function(): Promise<object>} deps.getClient - resolves to a connected `@temporalio/client` `Client`
 * @param {(function(): Promise<{graph:object, nodeMeta:object, flowVersion:string}>|{graph:object, nodeMeta:object, flowVersion:string})} deps.currentFlowInfo
 * @param {function(string): object} deps.getNode - Node-RED node lookup by id; falsy return => unknown node
 * @param {{workflowTaskQueue:string, activityTaskQueue:string}} deps.temporalConfig
 * @param {number} [deps.nodeExecutionTimeoutMs]
 * @param {number} [deps.syncTimeoutMs] - issue #58 M4: bound (ms) for the sync route's wait on `handle.result()`; defaults to `DEFAULT_SYNC_TIMEOUT_MS` (60000). M5 should wire a `--http-sync-timeout-ms` CLI flag through to this.
 * @param {string} [deps.host] - defaults to "127.0.0.1"
 * @param {number} [deps.port] - REQUIRED to actually `listen()`; the server is otherwise inert
 * @returns {{server:import("http").Server, listen:function(): Promise<{host:string, port:number}>, close:function(): Promise<void>, address:function(): (object|null)}}
 */
function createHttpIngressServer(deps) {
    deps = deps || {};
    if (typeof deps.getClient !== "function") {
        throw new Error("createHttpIngressServer: deps.getClient is required");
    }
    if (typeof deps.getNode !== "function") {
        throw new Error("createHttpIngressServer: deps.getNode is required");
    }
    if (!deps.currentFlowInfo) {
        throw new Error("createHttpIngressServer: deps.currentFlowInfo is required");
    }
    if (!deps.temporalConfig) {
        throw new Error("createHttpIngressServer: deps.temporalConfig is required");
    }

    const server = http.createServer(createRequestListener(deps));
    const host = deps.host || "127.0.0.1";
    const port = deps.port;

    return {
        server: server,
        /**
         * @returns {Promise<{host:string, port:number}>}
         */
        listen() {
            return new Promise(function(resolve, reject) {
                function onError(err) {
                    server.removeListener("listening", onListening);
                    reject(err);
                }
                function onListening() {
                    server.removeListener("error", onError);
                    const bound = server.address();
                    resolve({ host: bound.address, port: bound.port });
                }
                server.once("error", onError);
                server.once("listening", onListening);
                server.listen(port, host);
            });
        },
        /**
         * @returns {object|null} same shape as `net.Server#address()`
         */
        address() {
            return server.address();
        },
        /**
         * @returns {Promise<void>}
         */
        close() {
            return new Promise(function(resolve, reject) {
                server.close(function(err) {
                    if (err) {
                        reject(err);
                        return;
                    }
                    resolve();
                });
            });
        }
    };
}

module.exports = {
    createHttpIngressServer,
    // exported for unit tests / potential reuse - plain, DI-free helpers
    matchAsyncRoute,
    matchSyncRoute,
    sanitizeHeaders,
    readBodyCapped,
    parseBody,
    buildEnvelope,
    deriveWorkflowId,
    startFlowWorkflow,
    writeSyncSuccessResponse,
    isValidHttpStatus,
    MAX_BODY_BYTES,
    MAX_IDEMPOTENCY_KEY_BYTES,
    DEFAULT_SYNC_TIMEOUT_MS
};
